			title = "概述",
			text = [=[勇士之墓是{link:silithus}希利苏斯{/link}东北部的一片墓地，是那些倒在荒野中的人最后的安息之所。它远离虫巢和营地。{link:cenarion-circle}塞纳里奥议会{/link}的代理人{link:layo-starstrike}莱耶·星击{/link}在墓地旁接待旅人。与他一同等候的还有{link:shadow-council}议会{/link}的另一位仆从，以及一位皮革制品商人。从这里出发，通往{link:southwind-village}南风村{/link}废墟的道路向西南延伸。]=],
		},
	},
})

Translate("zhCN", "hive-ashi", {
