			title = "概述",
			text = [=[雷戈虫巢是{link:silithus}希利苏斯{/link}南部的虫巢。它的钻地者、伏击者、喷火者和奴役者听命于领主希尔希克斯。{link:explorers-league}探险者协会{/link}的{link:dwarves}矮人{/link}为了寻找遗物进入其中，发现了一块雕文水晶。{link:night-elves}暗夜精灵{/link}女祭司{link:natalia-mar-alith}娜塔莉亚·玛尔利斯{/link}把脸颊贴在水晶上，陷入了恍惚。几周之后，她逃回了虫巢，{link:qiraji}异种蝎{/link}为她让开了一条路。她再也没有出来。]=],
		},
	},
})

Translate("zhCN", "bronzebeard-encampment", {
