	sections = {
		{
			title = "概述",
			text = [=[水晶谷位于{link:silithus}希利苏斯{/link}的西北角。空气和大地的{link:elements}元素{/link}生物在这里自由游荡。{link:twilight-s-hammer}暮光之锤{/link}的一座营地曾经坐落于此。如今只有散落的木料和帆布标示着那个地点，还有一块泥板的碎片埋在沙中。泥板上讲述了一座北方的营地，那是第一个完成风之石的营地。一份邪教的公报则讲述了一座北方营地被其成员召唤来的一位领主所摧毁。在这片被蹂躏的土地边缘，一位大领主正在等待，并谈论着风之王子。]=],
		},
	},
})

