Translate("zhCN", "qiraji", {
	title = "其拉虫人",
	aliases = { "异种蝎" },
	sections = {
		{
			title = "概述",
			text = [=[其拉虫人是南方沙漠中一个古老而有智慧的昆虫种族。他们在{link:silithus}希利苏斯{/link}建起了安其拉要塞，并从那里指挥异种蝎，也就是充斥这片土地上各个虫巢的成群昆虫。异种蝎数不胜数，每时每刻都有更多的孵化出来。其拉虫人是它们的主人：他们不是野兽，而是谋划者，有着自己的将军和君王。]=],
		},
		{
			title = "起源",
			text = [=[{link:kalimdor}卡利姆多{/link}最古老的史书讲述了阿基尔，一个曾与远古{link:trolls}巨魔{/link}交战的昆虫帝国。当阿基尔被击退后，他们的一部分族人撤往南方，来到后来成为{link:silithus}希利苏斯{/link}的土地，并在那里成为了其拉虫人。{link:night-elves}暗夜精灵{/link}记述那场战争的书中说，其拉虫人曾经争夺卡利姆多大部分地区的统治权。]=],
		},
		{
			title = "虫群",
			text = [=[异种蝎并非独自行动。三座虫巢中各立着一块雕文水晶，{link:cenarion-circle}塞纳里奥议会{/link}的学者们相信，其拉虫人以及其他尚不为人知的力量，正是通过这些水晶向虫群传递消息。每座虫巢都有自己的领主，当雕文发出召唤时，领主们便会聚集起来。]=],
		},
		{
			title = "神殿中的力量",
			text = [=[在{link:war-of-the-shifting-sands}流沙之战{/link}期间，巨龙{link:arei}艾雷{/link}苟斯感觉到安其拉的大神殿中有一种奇异而微弱的魔法。没有一头巨龙能够触及它的源头。他们开始相信，那里有某种东西不仅控制着异种蝎，甚至控制着其拉虫人本身。一千年后，一个触碰了雕文水晶的{link:night-elves}暗夜精灵{/link}说出了它的名字：{red:c-thun}克苏恩{/red}。]=],
		},
	},
})

Translate("zhCN", "war-of-the-shifting-sands", {
	title = "流沙之战",
	sections = {
		{
			title = "概述",
			text = [=[流沙之战发生在将近一千年前，交战双方是{link:night-elves}暗夜精灵{/link}和安其拉的{link:qiraji}其拉虫人{/link}。这场战争并没有以胜利告终，而是以一座{link:the-stockade}监狱{/link}告终。]=],
		},
		{
			title = "入侵",
			text = [=[{link:qiraji}其拉虫人{/link}在拉贾克斯将军的率领下从安其拉出征，身后跟着无穷无尽的异种蝎虫群。{link:fandral-staghelm}范达尔·鹿盔{/link}集结{link:night-elves}暗夜精灵{/link}的军队迎战，他的儿子{link:valstann-staghelm}瓦尔斯坦{/link}与他并肩作战。暗夜精灵记述那场战争的书中说，{link:vanndar-stormpike}范达尔{/link}命令瓦尔斯坦守住{link:southwind-village}南风村{/link}。在村子废墟中找到的一本日志讲述了更多：安其拉的双子皇帝在那里设下了陷阱，瓦尔斯坦被俘，拉贾克斯当着他父亲大军的面将他处死。战争持续了数月。最终整个{link:silithus}希利苏斯{/link}都失守了，溃败的暗夜精灵军队经由{link:un-goro-crater}安戈洛{/link}被一路赶回{link:tanaris}塔纳利斯{/link}。]=],
		},
		{
			title = "巨龙",
			text = [=[在那里，受挫的{link:vanndar-stormpike}范达尔{/link}去找{red:nozdormu}诺兹多姆{/red}之子{link:arnak-grimtotem}阿纳克{/link}洛斯，恳求青铜龙的援助。阿纳克洛斯拒绝了，直到{link:qiraji}其拉虫人{/link}胆敢进攻{link:caverns-of-time}时光之穴{/link}。就连青铜龙军团也挡不住虫群，于是阿纳克洛斯向其他守护巨龙的子嗣求助。梅里莎拉代表{red:ysera}伊瑟拉{/red}的龙群前来，凯{link:farmer-ray}雷{/link}斯特{link:razzle-sprysprocket}拉兹{/link}代表{link:alexstrasza}阿莱克丝塔萨{/link}的龙群，{link:arei}艾雷{/link}苟斯代表{red:malygos}玛里苟斯{/red}的龙群。他们在安其拉的高空中看到，无论多少武力都无法结束这场战争。他们决定把敌人封在它自己的城市里。]=],
		},
		{
			title = "城墙与权杖",
			text = [=[他们汲取{link:night-elves}暗夜精灵{/link}和巨龙双方的力量，在安其拉周围筑起了一道巨大的屏障。梅里莎拉、凯{link:farmer-ray}雷{/link}斯特{link:razzle-sprysprocket}拉兹{/link}和{link:arei}艾雷{/link}苟斯冲向{link:qiraji}其拉虫人{/link}以争取时间，{link:arnak-grimtotem}阿纳克{/link}洛斯和{link:vanndar-stormpike}范达尔{/link}则封住了大门。完成之后，阿纳克洛斯交给范达尔一根可以再次打开屏障的权杖。这位大德鲁伊正为儿子悲痛，他把权杖朝屏障掷去，将它摔得粉碎。阿纳克洛斯收集起碎片，交给四大巨龙军团保管，使任何人都无法轻易让它恢复完整。]=],
		},
	},
})

Translate("zhCN", "abyssal-council", {
	title = "深渊议会",
	aliases = { "深渊高阶议会" },
	sections = {
		{
			title = "概述",
			text = [=[深渊议会是一个由{link:elements}元素{/link}贵族组成的等级体系，{link:twilight-s-hammer}暮光之锤{/link}在{link:silithus}希利苏斯{/link}侍奉着他们。邪教称他们为主人，并通过营地中的风之石与他们交谈。{link:cenarion-circle}塞纳里奥议会{/link}已经得知，深渊议会通过那些石头控制着邪教，邪教徒们从它那里接受命令。]=],
		},
		{
			title = "等级",
			text = [=[最底层是圣殿骑士：赤红圣殿骑士、碧蓝圣殿骑士、灰白圣殿骑士和大地圣殿骑士。他们之上是四位{link:duke-nicholas-zverenhoff}公爵{/link}：烈焰公爵、深渊公爵、微风公爵和碎石公爵。最高层是由四位领主组成的高阶{link:shadow-council}议会{/link}：斯卡德诺克斯王子、大元帅维拉希斯、卡祖姆{link:the-baron}男爵{/link}和斯克沃尔领主。]=],
		},
		{
			title = "风之石",
			text = [=[邪教自己的规矩很严格。入会者可以召唤圣殿骑士，但必须穿着规定的服饰，否则石头的防御就会苏醒。只有佩戴地位徽章的人才能与{link:duke-nicholas-zverenhoff}公爵{/link}交谈。只有暮光领主才能召唤高阶{link:shadow-council}议会{/link}，任何试图这样做的外人都要被烧成灰烬。议会的一位工匠已经学会了锻造这种徽章。有了一枚徽章，再穿上邪教自己的服饰，一位勇敢的战士就可以把议会的贵族从石中召唤出来并将其击倒。]=],
		},
	},
})

