			text = [=[拉洛尚独自站在{link:cenarion-hold}塞纳里奥要塞{/link}以东的沙漠中。他说，将近一千年前，{link:qiraji}其拉虫人{/link}正是从这里开始向{link:kalimdor}卡利姆多{/link}进军的。他是那个时代留存下来的少数人之一，同时被过去和现在所束缚。他不知道自己为什么必须留下。他只知道他必须留下。]=],
		},
		{ title = "意义", text = "拉洛尚已经被杀死过一百次，而每一次他都在原地重新醒来。有人说他受了诅咒。也有人称他为一个新时代的先驱。" },
		{
			title = "事迹",
			text = [=[• 他在{link:qiraji}其拉虫人{/link}入侵开始的地方守望。
• 他警告说，古老的力量正在躁动，噩梦已经开始从{link:emerald-dream}翡翠梦境{/link}中涌出。]=],
		},
	},
	bonds = {
		{ id = "baristolth-of-the-shifting-sands", name = "流沙守望者巴里斯托尔斯", note = "另一位从古老战争中留下来的人" },
	},
})

